// Navigation, prototype controls and real browser-local interactions.
let historyStack=[],toastTimer,focusedTextarea=null,menuOpen=false,overviewBuilt=false;
const editRoutes=new Set(['profile-identity','profile-persona','profile-model','profile-appearance','message-edit','api-edit','api-new','memory-edit','memory-new','lore-entry-edit','lore-entry-new','injection-edit','skill-edit','mcp-edit','file-editor','quick-edit','regex-edit']);
function persist(){storage.write('toggles',Object.fromEntries(Object.entries(state.toggles).filter(([k])=>k!=='session-full-trust')));storage.write('fields',state.fields);state.dirty=false;state.entryFields={...state.fields}}
function notify(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2800)}
function navigate(route,replace=false){if(!pages.some(p=>p.id===route))return;if(!replace&&state.route!==route)historyStack.push(state.route);state.route=route;if(route==='chat'||route==='chat-running'||route==='chat-approval')state.toggles['session-full-trust']=false;state.spoken=false;state.dirty=false;state.entryFields={...state.fields};closeMenu();document.getElementById('dialogLayer').innerHTML='';if(location.hash.slice(1)!==route)history.replaceState(null,'','#'+route);render();}
function render(){const p=pages.find(p=>p.id===state.route)||pages[0];document.getElementById('app').innerHTML=p.render();document.getElementById('phone').dataset.theme=state.theme;document.getElementById('pageTitle').textContent=p.title;document.getElementById('pageDescription').textContent=p.description;document.getElementById('currentCategory').textContent=p.group.split(' / ')[1];document.getElementById('pageNumber').textContent=String(pages.indexOf(p)+1).padStart(2,'0');document.getElementById('pageNotes').innerHTML=(p.notes.length?p.notes:['页面内容区可独立滚动，操作保持清晰可达。','继承统一主题、44 px 触控目标与单列导航。']).map((t,i)=>`<div class="annotation-item"><span>0${i+1}</span><div>${t}</div></div>`).join('');document.getElementById('relatedPages').innerHTML=p.related.map(id=>{const q=pages.find(p=>p.id===id);return q?`<a class="related-link" href="#${id}" data-route="${id}">${q.title}${icon('right')}</a>`:''}).join('');document.querySelectorAll('.nav-link').forEach(n=>n.classList.toggle('active',n.dataset.route===p.id));document.getElementById('themeButton').textContent=state.theme==='dark'?'浅色':'深色';if(state.route==='home'&&state.filter!=='全部'){document.querySelectorAll('#app .session').forEach(n=>n.hidden=n.dataset.profile!==state.filter)}applyAccent();document.title=p.title+' · 言枢 Messages 原型';}
function applyAccent(){const hex=state.accent.slice(1);const c=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16));const light=c.map(x=>Math.round(x+(255-x)*.55));document.documentElement.style.setProperty('--accent',state.accent);document.documentElement.style.setProperty('--accent-text',state.theme==='dark'?`rgb(${light.join(',')})`:state.accent);document.documentElement.style.setProperty('--accent-soft',state.theme==='dark'?`rgb(${c.map(x=>Math.round(x*.26)).join(',')})`:`rgb(${c.map(x=>Math.round(x+(255-x)*.88)).join(',')})`);document.querySelectorAll('.mini-container .phone').forEach(n=>n.dataset.theme=state.theme)}
function closeMenu(){document.querySelectorAll('.menu-panel,.menu-scrim').forEach(x=>x.remove());menuOpen=false}
function menu(message=false){if(menuOpen){closeMenu();return}menuOpen=true;const items=message?[['复制','copy','copy'],['编辑消息','edit','message-edit'],['从这里分支','branch','fork'],['重新生成','refresh','regenerate'],['朗读','voice','speak'],['翻译','translate','translation'],['删除','trash','delete-message']]:state.route.startsWith('chat')?[['会话设置','settings','chat-settings'],['模型选择','cloud','model-picker'],['文件与附件','attach','attachments'],['会话用量','clock','usage'],['群聊成员','group','group-members'],['导出会话','export','conversation-export'],['需要你回答','person','ask-user']]:[['新建会话','plus','new-chat'],['群聊讨论','group','group-chat'],['页面覆盖','book','coverage'],['全部页面总览','home','overview'],['返回主界面','home','home']];const actions=new Set(['copy','regenerate','speak','delete-message','overview']);document.getElementById('app').insertAdjacentHTML('beforeend',`<div class="menu-scrim" data-action="close-menu"></div><div class="menu-panel">${items.map(([title,i,target])=>`<button class="row" ${actions.has(target)?`data-action="${target}"`:`data-route="${target}"`}><span class="row-icon">${icon(i)}</span><span class="row-body"><b>${title}</b></span></button>`).join('')}</div>`)}
function confirmDialog(title,text,callback,label='确认'){document.getElementById('dialogLayer').innerHTML=`<div class="dialog-scrim"><div class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h3>${esc(title)}</h3><p>${esc(text)}</p><div class="actions">${btn('取消','cancel-dialog','secondary')}${btn(label,'confirm-dialog')}</div></div></div>`;window.confirmPrototypeAction=callback;document.querySelector('[data-action="cancel-dialog"]').focus()}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已下载原型示例文件')}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('已复制')}catch{notify('浏览器未允许剪贴板访问，可选中文本手动复制')}}
function pickFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>{if(input.files[0])callback(input.files[0])};input.click()}
function toggleOverview(){const showing=!document.getElementById('overview').hidden;document.getElementById('stage').hidden=!showing;document.getElementById('overview').hidden=showing;document.getElementById('overviewButton').textContent=showing?'页面总览':'交互预览';if(!showing&&!overviewBuilt){buildOverview();overviewBuilt=true}if(!showing)window.scrollTo({top:0,behavior:'smooth'})}
function buildOverview(){const groups=[...new Set(pages.map(p=>p.group))];document.getElementById('overview').innerHTML=`<h1>所有页面，都在这里。</h1><p>${pages.length} 个页面与状态 · 点击标题进入交互预览 · 每个表单都有实际内容</p>`+groups.map(g=>`<section class="overview-group"><h2>${g}</h2><div class="overview-grid">${pages.filter(p=>p.group===g).map(p=>`<article class="overview-card"><div class="mini-container" data-route="${p.id}" role="button" tabindex="0" aria-label="打开${p.title}"><div class="phone" data-theme="${state.theme}"><div class="status-bar"><span>10:42</span><span>${icon('wifi')}${icon('battery')}</span></div><div class="app">${p.render().replaceAll(/id="[^"]*"/g,'')}</div><div class="system-nav">${icon('back')}${icon('home')}${icon('search')}</div></div></div><a href="#${p.id}" data-route="${p.id}">${p.title}<small>${String(pages.indexOf(p)+1).padStart(2,'0')}</small></a></article>`).join('')}</div></section>`).join('');applyAccent()}
function buildNav(query=''){const groups=[...new Set(pages.map(p=>p.group))];document.getElementById('pageNav').innerHTML=groups.map(g=>{const filtered=pages.filter(p=>p.group===g&&(!query||(p.title+' '+p.id).toLowerCase().includes(query.toLowerCase())));return filtered.length?`<section class="nav-group"><button data-action="collapse-group">${g}${icon('down')}</button><div>${filtered.map(p=>`<a class="nav-link ${p.id===state.route?'active':''}" data-route="${p.id}" href="#${p.id}"><span>${String(pages.indexOf(p)+1).padStart(2,'0')}</span>${p.title}</a>`).join('')}</div></section>`:''}).join('');document.getElementById('pageCount').textContent=pages.length+' 屏'}
function action(a,element){const value=element?.dataset.value;
 switch(a){
 case 'back':if(menuOpen){closeMenu();return}if(document.getElementById('dialogLayer').innerHTML){document.getElementById('dialogLayer').innerHTML='';return}if(state.dirty&&editRoutes.has(state.route)){confirmDialog('放弃未保存的修改？','这页的修改尚未保存。你可以取消返回继续编辑。',()=>{state.fields={...state.entryFields};state.dirty=false;navigate(historyStack.pop()||'home',true)},'放弃修改');return}navigate(historyStack.pop()||'home',true);break;
 case 'save':persist();notify('已保存原型配置');break;
 case 'menu':menu();break;case 'message-menu':menu(true);break;case 'close-menu':closeMenu();break;
 case 'theme':state.theme=state.theme==='dark'?'light':'dark';storage.write('theme',state.theme);render();break;
 case 'accent':state.accent=value;storage.write('accent',value);render();break;
 case 'overview':toggleOverview();break;
 case 'filter':state.filter=value;render();if(value!=='全部')document.querySelectorAll('#app .session').forEach(n=>n.hidden=n.dataset.profile!==value);break;
 case 'profile-filter':element.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===element));document.querySelectorAll('#app .profile-row').forEach(n=>n.hidden=value!=='全部'&&n.dataset.tags!==value);break;
 case 'memory-filter':element.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===element));document.querySelectorAll('#app .memory').forEach(n=>n.hidden=value!=='全部'&&!n.dataset.searchItem.includes(value));break;
 case 'select-model':state.model=value;render();notify('已选择 '+value);break;
 case 'favorite':state.favorites=state.favorites.includes(value)?state.favorites.filter(m=>m!==value):[...state.favorites,value];storage.write('favorites',state.favorites);render();break;
 case 'apply-model':storage.write('model',state.model);persist();navigate(historyStack.pop()||'chat',true);notify('模型已设为 '+state.model);break;
 case 'add-model':if(!state.fields['manual-model']?.trim()){notify('请输入模型标识');return}state.model=state.fields['manual-model'];storage.write('model',state.model);navigate('model-picker');notify('模型已添加');break;
 case 'start-chat':navigate('chat-empty');break;
 case 'send':{const input=document.getElementById('composerInput');if(!input?.value.trim()){notify('先写一条消息');return}const message=input.value.trim();state.messages.push(message);if(state.running||state.route==='chat-running'){notify('已追加到当前任务');input.value='';return}state.running=true;navigate('chat-running');setTimeout(()=>{state.running=false;if(state.route==='chat-running'){navigate('chat',true);notify('演示回复已完成')}},2200);break}
 case 'interrupt':state.running=false;navigate('chat',true);notify('已停止，保留现有内容');break;
 case 'quick':{const input=document.getElementById('composerInput');if(input){input.value=value;input.focus();notify('已填入草稿，可修改后发送')}break}
 case 'regenerate':state.branch=2;closeMenu();navigate('chat-branches');notify('已添加一个候选回复');break;
 case 'branch-prev':state.branch=Math.max(1,state.branch-1);render();break;case 'branch-next':state.branch=Math.min(3,state.branch+1);render();break;
 case 'speak':state.spoken=true;render();notify('朗读状态演示');break;case 'stop-speech':state.spoken=false;if(state.route==='chat-speaking')navigate('chat',true);else render();break;
 case 'translate':navigate('chat-translated');break;
 case 'retry':state.running=true;navigate('chat-running');setTimeout(()=>{state.running=false;if(state.route==='chat-running')navigate('chat',true)},1800);break;
 case 'retry-network':navigate('chat');notify('已进入联网状态演示');break;
 case 'approve':case 'approve-always':{const remember=a==='approve-always'||document.querySelector('#app input[type="checkbox"]')?.checked;confirmDialog(remember?'确认记住文件写入授权':'允许这次文件写入',remember?'将记住当前档案内 write_file 的授权，可在权限页撤销。':'仅允许写入 engineering/files/login-settings.json。',()=>{state.running=true;navigate('chat-running');notify('已批准，演示任务继续')},remember?'记住授权':'允许一次');break}
 case 'reject':state.running=false;navigate('chat',true);notify('已拒绝文件写入，原文件保持不变（演示）');break;
 case 'answer':navigate('chat-running');notify('已提交选择，演示任务继续');break;
 case 'attach':navigate('attachment-add');break;
 case 'add-attachment':state.attachment=true;navigate('chat');notify('附件已加入输入区');break;case 'remove-attachment':state.attachment=false;render();break;
 case 'save-message':navigate('chat');notify('消息修改已保存到原型');break;case 'fork':navigate('chat-branches');notify('已创建演示会话分支');break;
 case 'add-member':navigate('group-members');notify('已加入选中的演示成员');break;case 'group-mode':navigate('group-chat');notify('回复模式已更新');break;
 case 'create-profile':if(!state.fields['new-profile-name']?.trim()){notify('请输入档案名称');return}persist();navigate('profile');notify('已创建档案（演示）');break;
 case 'create-lorebook':if(!document.querySelector('#app input')?.value.trim()){notify('请输入世界书名称');return}persist();navigate('lorebook-detail');notify('已创建演示世界书');break;
 case 'pick-avatar':case 'pick-image':pickFile('image/png,image/jpeg',f=>{const url=URL.createObjectURL(f);navigate(a==='pick-avatar'?'avatar':'attachment-preview');const area=document.querySelector('#app .profile-hero .avatar,#app .file-art');if(area){area.innerHTML=`<img src="${url}" alt="本地图片预览" style="width:100%;height:100%;object-fit:contain">`}notify('仅本地预览：'+f.name)});break;
 case 'avatar-reset':notify('已恢复名称首字头像');break;
 case 'pick-card':case 'pick-card-json':pickFile(a==='pick-card'?'.png':'.json',async f=>{if(f.size>5*1024*1024){navigate('import-error');notify('角色卡文件超过 5 MB');return}if(a==='pick-card-json'){try{const card=JSON.parse(await f.text());const data=card.data||card;if(!data.name){navigate('import-error');return}state.fields['import-preview:角色名称']=String(data.name);navigate('import-preview');notify('已读取 JSON 名称，其他内容为演示')}catch{navigate('import-error')}}else{navigate('import-error');notify('网页不解析 PNG 内嵌字段；可使用演示角色卡')}});break;
 case 'parse-card-url':if(!/^https:\/\//.test(state.fields['card-url']||'')){notify('请输入有效的 HTTPS 链接');return}navigate('import-preview');break;
 case 'import-next':navigate('import-options');break;case 'finish-import':navigate('import-done');break;
 case 'insert-variable':{const t=focusedTextarea&&document.contains(focusedTextarea)?focusedTextarea:document.querySelector('#app textarea');if(t){const s=t.selectionStart,e=t.selectionEnd;t.value=t.value.slice(0,s)+value+t.value.slice(e);t.focus();t.setSelectionRange(s+value.length,s+value.length);t.dispatchEvent(new Event('input',{bubbles:true}));notify('已插入变量')}break}
 case 'validate-json':try{document.querySelectorAll('#app textarea').forEach(t=>JSON.parse(t.value));persist();notify('JSON 校验通过，已保存')}catch{notify('JSON 格式有误，请检查逗号与引号')}break;
 case 'test-connection':navigate('api-test');notify('连接测试为演示结果');break;case 'refresh-models':navigate('model-picker');notify('已刷新演示模型目录');break;
 case 'save-regex':try{new RegExp(state.fields['regex-pattern']??'<think>[\\s\\S]*?</think>');persist();notify('表达式有效，已保存')}catch{notify('表达式无效，请检查语法')}break;
 case 'run-regex':{const inputs=document.querySelectorAll('#app input');const text=document.querySelector('#app textarea').value;try{const expression=inputs[0].value;if(expression.length>300||text.length>10000){notify('原型限制：表达式 300 字符、样例 10,000 字符');return}if(/\([^)]*[+*][^)]*\)[+*{]/.test(expression)){notify('表达式包含嵌套重复，请简化后再测试');return}document.getElementById('regexResult').textContent=text.replace(new RegExp(expression,'g'),inputs[1].value)}catch(e){document.getElementById('regexResult').textContent='表达式错误：'+e.message}break}
 case 'save-lore':{const keys=document.querySelectorAll('#app input');const content=document.querySelector('#app textarea');if(!keys[0]?.value.trim()||!keys[1]?.value.trim()||!content?.value.trim()){notify('名称、关键词与内容不能为空');return}persist();notify('世界书条目已保存');break}
 case 'rebuild-index':document.getElementById('indexProgress').hidden=false;notify('正在重建演示索引');setTimeout(()=>{const el=document.getElementById('indexProgress');if(el)el.hidden=true;notify('87 条记忆索引已就绪')},1400);break;
 case 'clean-memory':confirmDialog('确认整理记忆','演示将合并 3 组重复项，并移除 4 条过时摘要。',()=>{navigate('memory');notify('整理完成（演示）')});break;
 case 'test-mcp':navigate('mcp-detail');notify('MCP 连接为演示结果');break;
 case 'compress':navigate('context-preview');break;case 'confirm-compress':navigate('context');notify('压缩完成（演示），保留摘要与近期消息');break;
 case 'pick-document':pickFile('.txt,.md,.docx,.xlsx,.pptx,.pdf',f=>{if(f.size>25*1024*1024){notify('文件超过 25 MB');return}navigate('file-preview');notify('已选择 '+f.name+'；解析内容为演示')});break;
 case 'create-file':if(!state.fields['new-file-name']?.trim()){notify('请输入文件名');return}navigate('files');notify('演示文件已创建');break;
 case 'resolve-conflict':confirmDialog('继续保存文件','按当前所选方式处理演示文件冲突。',()=>{navigate('files');notify('文件冲突已处理（演示）')});break;
 case 'create-backup':navigate('backup-progress');break;case 'pick-backup':pickFile('.zip',f=>{state.selectedBackup=true;navigate('backup-preview');notify('已选择 '+f.name+'；校验结果为演示')});break;
 case 'restore-next':navigate('restore-confirm');break;
 case 'restore':if(!document.querySelector('#app input[name="restore-ack"]')?.checked){notify('请先确认你已检查恢复范围');return}confirmDialog('确认恢复备份','将按所选方式恢复 3 个档案、126 个会话与 308 条记忆（演示）。',()=>navigate('restore-result'),'开始恢复');break;
 case 'migrate':navigate('home');notify('旧数据导入完成（演示）');break;
 case 'clean-storage':confirmDialog('清理所选内容','缓存将可重新生成，导出副本按所选类别处理（演示）。',()=>{navigate('storage');notify('清理完成（演示）')});break;
 case 'restore-trash':navigate('trash');notify('已恢复演示项目');break;case 'restore-archived':navigate('conversations');notify('已恢复归档会话');break;
 case 'archive-selected':navigate('archived');notify('已归档选中会话（演示）');break;case 'move-selected':navigate('conversations');notify('会话及关联记忆已移动（演示）');break;
 case 'delete-message':case 'delete-conversation':case 'delete-selected':case 'delete-files':confirmDialog('移入回收区','选中内容将进入回收区，可以稍后恢复。',()=>{navigate(a==='delete-message'?'chat':'trash');notify('已移入回收区（演示）')},'移入回收区');break;
 case 'empty-trash':case 'permanent-delete':confirmDialog('永久删除？','此操作无法撤销。网页原型只展示确认流程，不删除真实数据。',()=>{navigate('trash');notify('永久删除流程已完成（演示）')},'永久删除');break;
 case 'clear-permissions':case 'revoke-permission':case 'revoke-folder':confirmDialog('撤销授权','相关操作将重新询问许可（演示）。',()=>{notify('已撤销演示授权');navigate(a==='revoke-folder'?'authorized-folders':'permissions')});break;
 case 'clear-log':confirmDialog('清空诊断日志','只清空当前演示日志，不影响会话内容。',()=>{document.querySelectorAll('#app .log-line').forEach(n=>n.remove());notify('演示日志已清空')});break;
 case 'cancel-dialog':document.getElementById('dialogLayer').innerHTML='';window.confirmPrototypeAction=null;break;
 case 'confirm-dialog':{const cb=window.confirmPrototypeAction;window.confirmPrototypeAction=null;document.getElementById('dialogLayer').innerHTML='';if(cb)cb();break}
 case 'copy':case 'copy-log':copyText(a==='copy-log'?'10:36:08 UTC HTTP POST api.deepseek.com 200 248ms':'一轮对话由过程轨道和最终输出组成。');closeMenu();break;
 case 'export-conversation':{const format=state.fields['export-format']||'Markdown';const sample={prototype:true,title:'重写时间线投影',messages:[{role:'user',content:'整理时间线的投影规则。'},{role:'assistant',content:'过程轨道与最终输出分开呈现。'}]};download('conversation.'+(format==='Markdown'?'md':format==='JSONL'?'jsonl':'json'),format==='Markdown'?'# 重写时间线投影\n\n> 原型示例\n\n用户：整理时间线的投影规则。\n\n助理：过程轨道与最终输出分开呈现。':format==='JSONL'?sample.messages.map(x=>JSON.stringify(x)).join('\n'):JSON.stringify(sample,null,2));break}
 case 'export-profile':download('engineering-prototype.json',JSON.stringify({prototype:true,name:'工程助理',model:state.model,description:'网页交互原型导出示例，不是实际工作区备份。'},null,2),'application/json');break;
 case 'download-backup':download('backup-prototype-info.txt','言枢备份原型说明\n这是网页演示下载，不含实际工作区数据，也不是恢复 ZIP。');break;
 case 'export-usage':download('usage-prototype.jsonl',JSON.stringify({prototype:true,time:'10:36:08',host:'api.deepseek.com',model:state.model,input:4210,output:1240,durationMs:8300}));break;
 case 'export-log':download('diagnostics-prototype.log','[prototype] 10:36:08 HTTP api.deepseek.com 200 248ms\n[prototype] 10:42:01 HTTP 429 RateLimit');break;
 case 'export-file':download('notes-prototype.txt','原型示例文件\n用户消息是唯一气泡，过程走轨道。');break;
 case 'export-skill':download('code-review-prototype.md','# 代码审查\n\n检查输入边界、异常处理与移动端性能。');break;
 case 'import-skill':pickFile('.md,.txt',f=>{navigate('skill-edit');notify('已选择 '+f.name+'，编辑内容为演示')});break;
 case 'duplicate-profile':notify('已复制档案（演示）');break;
 case 'select-workspace':case 'add-folder':confirmDialog('选择存储位置','真实 UWP 应用会打开系统文件夹选择器。网页原型演示授权后结果。',()=>{navigate('authorized-folders');notify('演示目录已添加')},'演示选择');break;
 case 'rebuild-workspace':notify('工作区索引重建完成（演示）');break;
 case 'collapse-group':element.nextElementSibling.hidden=!element.nextElementSibling.hidden;break;
 default:notify('演示操作：'+(element?.textContent.trim()||a));
 }
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-route],[data-action],[data-toggle]');if(!target||target.closest('.mini-container')){const miniature=e.target.closest('.mini-container');if(miniature){if(!document.getElementById('overview').hidden)toggleOverview();navigate(miniature.dataset.route)}return}if(target.disabled)return;if(target.dataset.route){e.preventDefault();if(!document.getElementById('overview').hidden)toggleOverview();navigate(target.dataset.route)}else if(target.dataset.toggle){const value=target.getAttribute('aria-checked')!=='true';target.setAttribute('aria-checked',String(value));state.toggles[target.dataset.toggle]=value;persist()}else action(target.dataset.action,target)});
document.addEventListener('focusin',e=>{if(e.target.tagName==='TEXTAREA')focusedTextarea=e.target});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){state.fields[t.dataset.field]=t.value;state.dirty=editRoutes.has(state.route)}if(t.dataset.range!==undefined){t.parentElement.querySelector('output').textContent=t.value+(t.hasAttribute('data-font-size')?' px':state.route.includes('appearance')?'%':'');if(t.hasAttribute('data-font-size'))document.getElementById('fontPreview').style.fontSize=t.value+'px'}if(t.dataset.search){const q=t.value.toLowerCase();const app=document.getElementById('app');app.querySelectorAll('[data-search-item]').forEach(n=>n.hidden=!(n.dataset.searchItem||'').toLowerCase().includes(q));if(t.dataset.search==='global'){app.querySelectorAll('.row').forEach(n=>n.hidden=!n.textContent.toLowerCase().includes(q));const matches=[...app.querySelectorAll('[data-search-item],.row')].some(n=>!n.hidden);document.getElementById('searchEmpty').hidden=matches;document.getElementById('searchResults').hidden=!matches}app.querySelectorAll('.model-group').forEach(n=>{if(q)n.open=true})}if(t.id==='composerInput'){t.style.height='42px';t.style.height=Math.min(110,t.scrollHeight)+'px'}});
document.addEventListener('change',e=>{if(e.target.dataset.field){state.fields[e.target.dataset.field]=e.target.value;state.dirty=editRoutes.has(state.route)}if(e.target.name==='theme-choice'){state.theme=e.target.parentElement.textContent.includes('浅色')?'light':'dark';storage.write('theme',state.theme);render()}});
document.addEventListener('toggle',e=>{if(e.target.dataset?.provider)storage.write('provider-'+e.target.dataset.provider,e.target.open)},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();action('back')}if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('pageSearch').focus()}if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('mini-container')){e.preventDefault();toggleOverview();navigate(e.target.dataset.route)}});
document.getElementById('pageSearch').addEventListener('input',e=>buildNav(e.target.value));
document.getElementById('themeButton').onclick=()=>action('theme');
document.getElementById('overviewButton').onclick=toggleOverview;
document.getElementById('viewportSelect').onchange=e=>{const w=Number(e.target.value),h=w===430?740:640;document.documentElement.style.setProperty('--phone-width',w+'px');document.documentElement.style.setProperty('--phone-height',h+'px');document.getElementById('viewportCaption').textContent=`${w} × ${h}`};
document.getElementById('navSearchIcon').innerHTML=icon('search');document.getElementById('statusIcons').innerHTML=icon('signal')+icon('wifi')+icon('battery');document.getElementById('systemBack').innerHTML=icon('back');document.getElementById('systemHome').innerHTML=icon('home');document.getElementById('systemSearch').innerHTML=icon('search');
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'home'));
buildNav();navigate(location.hash.slice(1)||'home',true);
// Read-only hooks for coverage verification and static review exports.
window.PROTOTYPE={pages,state,navigate,icon,render,buildOverview};






